  1 | import { useCallback, useRef, useState, useEffect } from "react";
  2 | import { usePlayerWithAudio } from "./hooks/usePlayerWithAudio";
  3 | import { useMetadata } from "./hooks/useMetadata";
  4 | import { useTauri } from "./hooks/useTauri";
  5 | import { useAudioVisualizer } from "./hooks/useAudioVisualizer";
  6 | import { useFavorites } from "./hooks/useFavorites";
  7 | import { useHistory } from "./hooks/useHistory";
  8 | import { usePlaylists } from "./hooks/usePlaylists";
  9 | import {
 10 |   TitleBar,
 11 |   Playlist,
 12 |   PlayerControls,
 13 |   ProgressBar,
 14 |   StatusBar,
 15 |   DriveBrowser,
 16 |   AudioVisualizer,
 17 |   HistoryPanel,
 18 |   PlaylistManager,
 19 | } from "./components";
 20 | import type { Track } from "./types";
 21 | 
 22 | function App() {
 23 |   const {
 24 |     state,
 25 |     play,
 26 |     pause,
 27 |     next,
 28 |     prev,
 29 |     seek,
 30 |     setVolume,
 31 |     addTrack,
 32 |     toggleShuffle,
 33 |     reorderPlaylist,
 34 |     toggleFavorite,
 35 |     loadFavorites: loadPlayerFavorites,
 36 |     audioRef,
 37 |   } = usePlayerWithAudio([]);
 38 | 
 39 |   const { processFiles } = useMetadata();
 40 |   const {
 41 |     state: tauriState,
 42 |     openFilePicker,
 43 |     filePathToUrl,
 44 |     sendNotification,
 45 |     registerShortcuts,
 46 |   } = useTauri();
 47 | 
 48 |   const { loadFavorites } = useFavorites();
 49 |   const history = useHistory();
 50 |   const playlists = usePlaylists();
 51 | 
 52 |   const [isLoading, setIsLoading] = useState(false);
 53 |   const [showDrive, setShowDrive] = useState(false);
 54 |   const [showHistory, setShowHistory] = useState(false);
 55 |   const [showPlaylistManager, setShowPlaylistManager] = useState(false);
 56 |   const [isCompact, setIsCompact] = useState(false);
 57 | 
 58 |   const fileInputRef = useRef<HTMLInputElement>(null);
 59 | 
 60 |   // Carrega favoritos salvos ao iniciar
 61 |   useEffect(() => {
 62 |     const savedFavorites = loadFavorites();
 63 |     if (savedFavorites.length > 0) {
 64 |       loadPlayerFavorites(savedFavorites);
 65 |     }
 66 |     // eslint-disable-next-line react-hooks/exhaustive-deps
 67 |   }, []);
 68 | 
 69 |   // Registra atalhos de teclado (Media Session API + Tauri global shortcuts)
 70 |   useEffect(() => {
 71 |     const cleanup = registerShortcuts({
 72 |       MediaPlayPause: () => (state.isPlaying ? pause() : play()),
 73 |       MediaNextTrack: () => next(),
 74 |       MediaPrevTrack: () => prev(),
 75 |       MediaStop: () => pause(),
 76 |     });
 77 | 
 78 |     return () => {
 79 |       cleanup.then((fn) => fn());
 80 |     };
 81 |   }, [registerShortcuts, state.isPlaying, pause, play, next, prev]);
 82 | 
 83 |   // Media Session API (navegador)
 84 |   useEffect(() => {
 85 |     if (!("mediaSession" in navigator)) return;
 86 | 
 87 |     navigator.mediaSession.metadata = new MediaMetadata({
 88 |       title: state.currentTrack?.title ?? "Llama Player",
 89 |       artist: state.currentTrack?.artist ?? undefined,
 90 |       album: state.currentTrack?.album ?? undefined,
 91 |     });
 92 | 
 93 |     navigator.mediaSession.setActionHandler("play", () => play());
 94 |     navigator.mediaSession.setActionHandler("pause", () => pause());
 95 |     navigator.mediaSession.setActionHandler("nexttrack", () => next());
 96 |     navigator.mediaSession.setActionHandler("previoustrack", () => prev());
 97 |   }, [state.currentTrack, play, pause, next, prev]);
 98 | 
 99 |   // Notificação ao trocar de música + histórico
100 |   useEffect(() => {
101 |     if (state.currentTrack && state.isPlaying) {
102 |       sendNotification(
103 |         `▶ ${state.currentTrack.title}`,
104 |         state.currentTrack.artist
105 |           ? `Por ${state.currentTrack.artist}`
106 |           : undefined
107 |       );
108 |       history.addEntry(state.currentTrack);
109 |     }
110 |   }, [state.currentTrack?.id, state.isPlaying]); // eslint-disable-line react-hooks/exhaustive-deps
111 | 
112 |   const visualizer = useAudioVisualizer(audioRef, state.isPlaying);
113 | 
114 |   const handleSelectTrack = (track: Track) => {
115 |     play(track);
116 |   };
117 | 
118 |   const handleOpenFile = async () => {
119 |     if (tauriState.isTauri) {
120 |       // Usa file picker nativo do Tauri
121 |       setIsLoading(true);
122 |       try {
123 |         const paths = await openFilePicker();
124 |         if (!paths || paths.length === 0) return;
125 | 
126 |         // Converte paths para File objects (via fetch do asset protocol)
127 |         const tracks: Track[] = [];
128 |         for (const path of paths) {
129 |           const url = await filePathToUrl(path);
130 |           const name = path.split(/[/\\]/).pop() || path;
131 |           tracks.push({
132 |             id: `local-${Date.now()}-${Math.random().toString(36).slice(2, 8)}`,
133 |             title: name.replace(/\.[^/.]+$/, ""),
134 |             duration: 0,
135 |             src: url,
136 |           });
137 |         }
138 | 
139 |         for (const track of tracks) {
140 |           addTrack(track);
141 |         }
142 | 
143 |         if (!state.currentTrack && tracks.length > 0) {
144 |           play(tracks[0]);
145 |         }
146 |       } catch (err) {
147 |         console.error("[Llama Player] Erro ao abrir arquivos:", err);
148 |       } finally {
149 |         setIsLoading(false);
150 |       }
151 |     } else {
152 |       // Fallback: input file HTML
153 |       fileInputRef.current?.click();
154 |     }
155 |   };
156 | 
157 |   const handleFileChange = useCallback(
158 |     async (e: React.ChangeEvent<HTMLInputElement>) => {
159 |       const files = e.target.files;
160 |       if (!files || files.length === 0) return;
161 | 
162 |       setIsLoading(true);
163 | 
164 |       try {
165 |         const fileArray = Array.from(files);
166 |         const tracks = await processFiles(fileArray);
167 | 
168 |         for (const track of tracks) {
169 |           addTrack(track);
170 |         }
171 | 
172 |         // If nothing is playing, start with the first track
173 |         if (!state.currentTrack && tracks.length > 0) {
174 |           play(tracks[0]);
175 |         }
176 |       } catch (err) {
177 |         console.error("[Llama Player] Erro ao processar arquivos:", err);
178 |       } finally {
179 |         setIsLoading(false);
180 |       }
181 | 
182 |       // Reset input so the same file can be selected again
183 |       e.target.value = "";
184 |     },
185 |     [processFiles, addTrack, state.currentTrack, play]
186 |   );
187 | 
188 |   const handleDropFiles = useCallback(
189 |     async (files: FileList) => {
190 |       setIsLoading(true);
191 |       try {
192 |         const fileArray = Array.from(files);
193 |         const tracks = await processFiles(fileArray);
194 |         for (const track of tracks) {
195 |           addTrack(track);
196 |         }
197 |         if (!state.currentTrack && tracks.length > 0) {
198 |           play(tracks[0]);
199 |         }
200 |       } catch (err) {
201 |         console.error("[Llama Player] Erro ao processar arquivos arrastados:", err);
202 |       } finally {
203 |         setIsLoading(false);
204 |       }
205 |     },
206 |     [processFiles, addTrack, state.currentTrack, play]
207 |   );
208 | 
209 |   const handleAddDriveTracks = useCallback(
210 |     (tracks: Track[]) => {
211 |       for (const track of tracks) {
212 |         addTrack(track);
213 |       }
214 |       if (!state.currentTrack && tracks.length > 0) {
215 |         play(tracks[0]);
216 |       }
217 |     },
218 |     [addTrack, state.currentTrack, play]
219 |   );
220 | 
221 |   return (
222 |     <div className="app">
223 |       <TitleBar />
224 | 
225 |       <main className="main-content">
226 |         <div className="toolbar">
227 |           <button
228 |             className="toolbar-btn"
229 |             onClick={handleOpenFile}
230 |             disabled={isLoading}
231 |             title="Abrir arquivo de áudio local"
232 |           >
233 |             {isLoading ? "⏳ Lendo metadados..." : "📂 Arquivo local"}
234 |           </button>
235 |           <input
236 |             ref={fileInputRef}
237 |             type="file"
238 |             accept="audio/*"
239 |             multiple
240 |             style={{ display: "none" }}
241 |             onChange={handleFileChange}
242 |           />
243 |           <button
244 |             className={`toolbar-btn ${showDrive ? "toolbar-btn-active" : ""}`}
245 |             onClick={() => setShowDrive((v) => !v)}
246 |             title="Google Drive"
247 |           >
248 |             ☁️ Drive
249 |           </button>
250 |           <button
251 |             className={`toolbar-btn ${showHistory ? "toolbar-btn-active" : ""}`}
252 |             onClick={() => setShowHistory((v) => !v)}
253 |             title="Histórico de reprodução"
254 |           >
255 |             🕐 Histórico
256 |           </button>
257 |           <button
258 |             className={`toolbar-btn ${showPlaylistManager ? "toolbar-btn-active" : ""}`}
259 |             onClick={() => setShowPlaylistManager((v) => !v)}
260 |             title="Gerenciar playlists"
261 |           >
262 |             📋 Playlists
263 |           </button>
264 |         </div>
265 | 
266 |         {showDrive && (
267 |           <DriveBrowser onAddTracks={handleAddDriveTracks} />
268 |         )}
269 | 
270 |         {showHistory && (
271 |           <HistoryPanel
272 |             entries={history.entries}
273 |             onSelectTrack={handleSelectTrack}
274 |             onClear={history.clear}
275 |           />
276 |         )}
277 | 
278 |         {showPlaylistManager && (
279 |           <PlaylistManager
280 |             playlists={playlists.playlists}
281 |             activePlaylistId={playlists.activePlaylistId}
282 |             currentTracks={state.playlist}
283 |             onSavePlaylist={playlists.saveCurrentPlaylist}
284 |             onLoadPlaylist={playlists.loadPlaylist}
285 |             onDeletePlaylist={playlists.deletePlaylist}
286 |             onRenamePlaylist={playlists.renamePlaylist}
287 |             onReplaceTracks={(tracks) => {
288 |               // Replace entire playlist
289 |               // First clear by reordering to empty, then add tracks
290 |               // We use a workaround: reorder to empty then add each track
291 |               // Actually, let's just load the tracks into the playlist
292 |               // by reordering to the saved tracks
293 |               if (tracks.length === 0) return;
294 |               // We need to replace the playlist. Since we have reorderPlaylist,
295 |               // we can set the playlist to the loaded tracks directly.
296 |               // The cleanest approach: reorder to the loaded tracks.
297 |               reorderPlaylist(tracks);
298 |               // Start playing the first track
299 |               play(tracks[0]);
300 |             }}
301 |             onClose={() => setShowPlaylistManager(false)}
302 |           />
303 |         )}
304 | 
305 |         <Playlist
306 |           tracks={state.playlist}
307 |           currentTrackId={state.currentTrack?.id ?? null}
308 |           isPlaying={state.isPlaying}
309 |           onSelectTrack={handleSelectTrack}
310 |           onReorderPlaylist={reorderPlaylist}
311 |           onDropFiles={handleDropFiles}
312 |           onToggleFavorite={toggleFavorite}
313 |         />
314 | 
315 |         <PlayerControls
316 |           currentTrack={state.currentTrack}
317 |           currentTrackId={state.currentTrack?.id ?? null}
318 |           isPlaying={state.isPlaying}
319 |           isShuffled={state.isShuffled}
320 |           isCompact={isCompact}
321 |           onPlay={() => play()}
322 |           onPause={pause}
323 |           onNext={next}
324 |           onPrev={prev}
325 |           onToggleShuffle={toggleShuffle}
326 |           onToggleFavorite={toggleFavorite}
327 |           onToggleCompact={() => setIsCompact((v) => !v)}
328 |         />
329 | 
330 |         <AudioVisualizer
331 |           frequencyData={visualizer.frequencyData}
332 |           waveformData={visualizer.waveformData}
333 |           isActive={visualizer.isActive}
334 |         />
335 | 
336 |         <ProgressBar
337 |           currentTime={state.currentTime}
338 |           duration={state.duration}
339 |           onSeek={seek}
340 |         />
341 |       </main>
342 | 
343 |       <StatusBar
344 |         isPlaying={state.isPlaying}
345 |         volume={state.volume}
346 |         onVolumeChange={setVolume}
347 |       />
348 |     </div>
349 |   );
350 | }
351 | 
352 | export default App;
